 LinearLayout root,body,nav; double balance=17280480.50; String owner="Мурзин Эдуард Сергеевич",nick="Жухлый_Эдик"; ArrayList<String> history=new ArrayList<>(); long lastCase=0; int cashback=0; double salaryBalance=0,creditDebt=0; long lastSalaryDay=-1,creditDue=0,lastPenaltyDay=0; int extraCards=0; double[] extraBalances=new double[5];
 int dp(int x){return (int)(x*getResources().getDisplayMetrics().density+.5f);}
