 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);balance=Double.longBitsToDouble(getPreferences(0).getLong("balanceBits",Double.doubleToLongBits(17280480.50)));owner=getPreferences(0).getString("owner",owner);nick=getPreferences(0).getString("nick",nick);String saved=getPreferences(0).getString("history","");if(!saved.isEmpty())history.addAll(Arrays.asList(saved.split("\\n")));light=getPreferences(0).getBoolean("light",false);applyTheme();lastCase=getPreferences(0).getLong("lastCase",0);cashback=getPreferences(0).getInt("cashback",0);salaryBalance=Double.longBitsToDouble(getPreferences(0).getLong("salaryBits",0));creditDebt=Double.longBitsToDouble(getPreferences(0).getLong("debtBits",0));lastSalaryDay=getPreferences(0).getLong("salaryDay",-1);creditDue=getPreferences(0).getLong("creditDue",0);lastPenaltyDay=getPreferences(0).getLong("penaltyDay",0);extraCards=Math.min(5,getPreferences(0).getInt("extraCards",0));for(int i=0;i<extraCards;i++)extraBalances[i]=Double.longBitsToDouble(getPreferences(0).getLong("extraBalance"+i,0));settleAccounts();pinScreen();}
 void applyTheme(){BG=light?0xfff3f5f8:0xff080e16;PANEL=light?0xffffffff:0xff111d2b;WHITE=light?0xff171e29:0xfff4f7fa;MUTED=light?0xff647184:0xff96a7b8;}
 void save(){android.content.SharedPreferences.Editor extraEdit=getPreferences(0).edit().putInt("extraCards",extraCards);for(int i=0;i<extraCards;i++)extraEdit.putLong("extraBalance"+i,Double.doubleToLongBits(extraBalances[i]));extraEdit.apply();getPreferences(0).edit().putLong("balanceBits",Double.doubleToLongBits(balance)).putString("owner",owner).putString("nick",nick).putString("history",String.join("\n",history)).putLong("lastCase",lastCase).putInt("cashback",cashback).putLong("salaryBits",Double.doubleToLongBits(salaryBalance)).putLong("debtBits",Double.doubleToLongBits(creditDebt)).putLong("salaryDay",lastSalaryDay).putLong("creditDue",creditDue).putLong("penaltyDay",lastPenaltyDay).apply();}
 String rub(double n){return String.format(new Locale("ru","RU"),"%,.2f ₽",n);}
