 void qrPayment(){heading("▦  QR-сканер");LinearLayout p=panel();line(p,"Сканирование QR","Камера или фотография из галереи");button("📷  Открыть камеру",()->requestQrCamera());button("▧  Выбрать изображение",()->{Intent i=new Intent(Intent.ACTION_GET_CONTENT);i.setType("image/*");startActivityForResult(i,4302);});button("Ввести данные вручную",()->service("Оплата по QR"));}
 @Override protected void onActivityResult(int requestCode,int resultCode,Intent data){super.onActivityResult(requestCode,resultCode,data);com.google.zxing.integration.android.IntentResult r=com.google.zxing.integration.android.IntentIntegrator.parseActivityResult(requestCode,resultCode,data);if(r!=null){if(r.getContents()!=null)showQrResult(r.getContents());return;}if(requestCode==4302&&resultCode==RESULT_OK&&data!=null){try{android.graphics.BitmapFactory.Options o=new android.graphics.BitmapFactory.Options();o.inSampleSize=2;android.graphics.Bitmap bmp;try(java.io.InputStream in=getContentResolver().openInputStream(data.getData())){bmp=android.graphics.BitmapFactory.decodeStream(in,null,o);}if(bmp==null)throw new Exception();int w=bmp.getWidth(),h=bmp.getHeight();int[] pixels=new int[w*h];bmp.getPixels(pixels,0,w,0,0,w,h);bmp.recycle();com.google.zxing.RGBLuminanceSource source=new com.google.zxing.RGBLuminanceSource(w,h,pixels);com.google.zxing.BinaryBitmap binary=new com.google.zxing.BinaryBitmap(new com.google.zxing.common.HybridBinarizer(source));String result=new com.google.zxing.MultiFormatReader().decode(binary).getText();showQrResult(result);}catch(Exception e){new AlertDialog.Builder(this).setTitle("QR не распознан").setMessage("Попробуй другое фото с чётким QR-кодом.").setPositiveButton("OK",null).show();}}}
 void showQrResult(String data){String value=data.length()>1500?data.substring(0,1500):data;new AlertDialog.Builder(this).setTitle("QR-код считан").setMessage("Содержимое:\n\n"+value+"\n\nДеньги не списываются.").setNegativeButton("Закрыть",null).setPositiveButton("Продолжить",(d,w)->service("Оплата по QR")).show();}

